// n8n Code node: "Prepare AI prompt"  (mode: Run Once for Each Item)
// Input: one row from get_send_queue. Output: the row + the DeepSeek request body.
const p = $json;
const isFollowUp = p.kind === 'followup';
const isFinal = isFollowUp && p.step >= p.max_followups;

let emailType = 'initial';
let guidance = 'First contact. Show you understand their kind of business, explain the offer in plain words, end with one low-pressure question about a short call.';
if (isFollowUp && !isFinal) {
  emailType = `follow-up ${p.step} of ${p.max_followups}`;
  guidance = 'Short, friendly nudge in the same thread. Do not repeat the first email. Add one new, concrete angle from the offer. End with a simple yes/no question.';
} else if (isFinal) {
  emailType = 'final follow-up';
  guidance = 'Politely close the loop: say this is the last note, make it easy to reply later or point you to the right person. No pressure.';
}

const system = [
  `You write short, personal B2B cold emails for ${p.sender_name}, ${p.sender_title}, based in Gaborone, Botswana.`,
  'Rules:',
  '- Plain text only. No links, no emojis, no bullet points, no markdown.',
  '- Initial email: 60 to 110 words. Follow-ups: 25 to 70 words.',
  `- Start with exactly "Hi ${p.first_name || 'there'},".`,
  '- In the initial email, mention the company name naturally once.',
  '- Use only the facts provided. Never invent statistics, percentages, prices, client names, results, or claims about the prospect.',
  '- One clear, low-pressure call to action, phrased as a question.',
  '- Do NOT add a sign-off, signature, or unsubscribe line. They are added automatically.',
  '- No filler like "I hope this email finds you well". Warm, direct, human, not salesy.',
  'Return only JSON: {"subject": "...", "body": "..."}.',
  'Subject: 2 to 7 words, specific, no clickbait, no exclamation marks, no emojis. For follow-ups return an empty subject.',
].join('\n');

const user = JSON.stringify({
  email_type: emailType,
  guidance,
  prospect: {
    first_name: p.first_name || '',
    company: String(p.company || '').replace(/\s*\(pty\)/gi, '').replace(/\s+(pty|ltd|limited|inc|llc)\.?(?=\s|$)/gi, '').replace(/\s{2,}/g, ' ').trim(),
    job_title: p.job_title || '',
    industry: p.industry,
    country: p.country || '',
    notes: p.notes || '',
  },
  our_offer: p.pitch,
  previous_subject: p.first_subject || '',
});

return {
  json: {
    ...p,
    ai_body: {
      model: 'deepseek-flash', // or 'deepseek-v4-pro' for the larger model
      response_format: { type: 'json_object' },
      max_tokens: 800,
      temperature: 0.7,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
};

// n8n Code node: "Validate & build email"  (mode: Run Once for Each Item)
// Input: DeepSeek response (or an error). Checks the AI copy with strict rules and
// falls back to a safe template if anything looks off. Then builds the raw email
// (plain text, threaded follow-ups, List-Unsubscribe header) for the Gmail API.
const p = $('Prepare AI prompt').item.json;
const isFollowUp = p.kind === 'followup';
const isFinal = isFollowUp && p.step >= p.max_followups;
const first = (p.first_name || '').trim();
const company = String(p.company || '').replace(/\s*\(pty\)/gi, '').replace(/\s+(pty|ltd|limited|inc|llc)\.?(?=\s|$)/gi, '').replace(/\s{2,}/g, ' ').trim();
const reasons = [];

// ---------- 1. read AI output ----------
let ai = null;
try {
  const content = $json?.choices?.[0]?.message?.content;
  if (!content) throw new Error('no AI content' + ($json?.error ? ': ' + JSON.stringify($json.error).slice(0, 200) : ''));
  ai = JSON.parse(content);
} catch (e) {
  reasons.push('AI unavailable: ' + e.message);
}

const words = (s) => (s.match(/\S+/g) || []).length;

function cleanBody(b) {
  b = String(b || '').replace(/\r/g, '').trim();
  // remove any sign-off the model added anyway
  b = b.replace(/\n+\s*(best( regards)?|kind regards|warm regards|regards|many thanks|thanks|thank you|cheers|sincerely)[,!.]?\s*(\n[\s\S]{0,120})?$/i, '').trim();
  b = b.replace(/\n{3,}/g, '\n\n');
  return b;
}

function check(subject, body) {
  const r = [];
  const all = subject + '\n' + body;
  const n = words(body);
  if (!isFollowUp && (n < 40 || n > 140)) r.push(`length ${n} words`);
  if (isFollowUp && (n < 12 || n > 90)) r.push(`length ${n} words`);
  if (/[\[\]{}<>]/.test(all)) r.push('placeholder/brackets');
  if (/\b(your name|company name|first name|insert|lorem)\b/i.test(all)) r.push('template text');
  if (/https?:\/\/|www\.|\.com\b|\.co\.bw\b/i.test(body)) r.push('contains link');
  if (/\d+\s?%/.test(all)) r.push('invented statistic');
  if (/\b(as an ai|language model|chatgpt|openai)\b/i.test(all)) r.push('AI giveaway');
  if (/\bguarantee/i.test(all)) r.push('guarantee claim');
  const g = body.match(/^\s*(hi|hello|hey|dear|dumela|good (morning|afternoon))\s+([^,\n!]+)/i);
  const expected = (first || 'there').toLowerCase();
  if (!g) r.push('missing greeting');
  else if (g[3].trim().toLowerCase() !== expected) r.push(`wrong name "${g[3].trim()}"`);
  if (!isFollowUp && company) {
    const key = company.toLowerCase().replace(/\b(pty|ltd|limited|\(pty\)|inc|llc)\b/g, '').replace(/[().,]/g, '').trim().split(/\s+/)[0];
    if (key && !body.toLowerCase().includes(key)) r.push('company not mentioned');
  }
  if (!isFollowUp) {
    if (subject.length < 3 || subject.length > 70) r.push('subject length');
    if (/[\n!]/.test(subject)) r.push('subject format');
    if (subject === subject.toUpperCase() && /[A-Z]{4,}/.test(subject)) r.push('subject all caps');
  }
  return r;
}

let subject = '', body = '', aiFallback = false;
if (ai) {
  subject = String(ai.subject || '').replace(/^["'\s]+|["'\s]+$/g, '').replace(/\s+/g, ' ');
  body = cleanBody(ai.body);
  reasons.push(...check(subject, body));
}

// ---------- 2. fallback template (deterministic, always safe) ----------
if (reasons.length) {
  aiFallback = true;
  const hi = `Hi ${first || 'there'},`;
  const who = company || 'your team';
  const senderFirst = (p.sender_name || '').split(' ')[0] || p.sender_name;
  const offer = String(p.pitch || '')
    .replace(/^BIYU AI Agency (build|help|create|make|design|automate)s\b/i, 'We $1')
    .trim();
  if (!isFollowUp) {
    subject = company ? `Quick question for ${company}` : 'Quick question';
    body = `${hi}\n\nI'm ${senderFirst} from BIYU AI Agency. ${offer}\n\nWould a short 15-minute call be worth it to see if this could help ${who}?`;
  } else if (!isFinal) {
    body = `${hi}\n\nJust bringing my note back to the top of your inbox. Would a quick call next week make sense, or is there someone else at ${who} I should speak to?`;
  } else {
    body = `${hi}\n\nI'll close the loop here so I don't crowd your inbox. If this becomes a priority for ${who} later, just reply to this email and I'll pick it up.`;
  }
}

// ---------- 3. final email text ----------
if (isFollowUp) subject = 'Re: ' + String(p.first_subject || subject || 'Quick question').replace(/^re:\s*/i, '');
const signature = `\n\n${p.sender_name}\n${p.sender_title}`;
const optOut = `\n\nIf this isn't relevant, just reply "stop" and I won't email you again.`;
const fullBody = body + signature + optOut;

// ---------- 4. raw MIME for the Gmail API ----------
const isTest = p.is_test === true || p.is_test === 'true';
const to = isTest ? p.notify_email : p.email;
const finalSubject = isTest ? `[TEST to ${p.email}] ${subject}` : subject;
const ascii = (s) => /^[\x20-\x7e]*$/.test(s);
const encWord = (s) => (ascii(s) ? s : '=?UTF-8?B?' + Buffer.from(s, 'utf8').toString('base64') + '?=');
const headers = [];
if (p.sender_email) {
  const name = String(p.sender_name || '').replace(/["\\\r\n]/g, '');
  headers.push(`From: ${ascii(name) ? `"${name}"` : encWord(name)} <${p.sender_email}>`);
  headers.push(`List-Unsubscribe: <mailto:${p.sender_email}?subject=unsubscribe>`);
}
headers.push(`To: ${to}`);
headers.push(`Subject: ${encWord(finalSubject)}`);
const threaded = isFollowUp && !isTest && p.thread_id;
if (threaded && p.rfc_message_id) {
  headers.push(`In-Reply-To: ${p.rfc_message_id}`);
  headers.push(`References: ${p.rfc_message_id}`);
}
headers.push('MIME-Version: 1.0', 'Content-Type: text/plain; charset="UTF-8"', 'Content-Transfer-Encoding: base64');
const b64 = Buffer.from(fullBody, 'utf8').toString('base64').replace(/.{1,76}/g, '$&\r\n');
const raw = Buffer.from(headers.join('\r\n') + '\r\n\r\n' + b64, 'utf8')
  .toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

const gmail_payload = threaded ? { raw, threadId: p.thread_id } : { raw };

return {
  json: {
    prospect_id: p.prospect_id,
    email: p.email,
    kind: p.kind,
    step: p.step,
    is_test: isTest,
    subject,
    body: fullBody,
    ai_fallback: aiFallback,
    fallback_reasons: reasons,
    gmail_payload,
  },
};

// n8n Code node: "Prepare log"  (mode: Run Once for Each Item)
// Input: Gmail "get message" metadata. Combines it with the send result for record_sent().
const built = $('Validate & build email').item.json;
const sent = $('Gmail: send').item.json;
const hdrs = $json?.payload?.headers || [];
const mid = hdrs.find((h) => String(h.name).toLowerCase() === 'message-id');
return {
  json: {
    prospect_id: built.prospect_id,
    kind: built.kind,
    step: built.step,
    is_test: built.is_test,
    subject: built.subject,
    body: built.body,
    ai_fallback: built.ai_fallback,
    gmail_id: sent.id || '',
    thread_id: sent.threadId || '',
    rfc_message_id: mid ? mid.value : '',
  },
};

// n8n Code node: "Classify send error"  (mode: Run Once for Each Item)
// Input: error item from "Gmail: send". Decides whether the address is bad
// (burn only this prospect) or the problem is global (limits, expired login).
const built = $('Validate & build email').item.json;
const e = $json.error ?? $json;
const text = typeof e === 'string' ? e : JSON.stringify(e);
const recipientProblem = /invalid to header|invalid recipient|recipient address|invalid email address|address rejected|no such user/i.test(text);
return {
  json: {
    prospect_id: built.prospect_id,
    kind: built.kind,
    step: built.step,
    is_test: built.is_test,
    subject: built.subject,
    recipient_problem: recipientProblem,
    error: text.slice(0, 900),
  },
};

// n8n Code node: "Classify inbound"  (mode: Run Once for Each Item)
// Input: a Gmail Trigger message (Simplify OFF). Works out if it is a real reply,
// an opt-out, a bounce or an auto-reply, and strips the quoted history.
const m = $json;
const header = (name) => {
  const v = m.headers?.[name.toLowerCase()];
  return v ? String(v).replace(/^[^:]+:\s*/, '').trim() : '';
};
const fromEmail = String(m.from?.value?.[0]?.address || m.from?.text || m.From || '').toLowerCase();
const subject = String(m.subject || m.Subject || '');
let text = String(m.text || m.snippet || '');
if (!text && m.html) text = String(m.html).replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, ' ');

// keep only the new part of the reply
let clean = text.replace(/\r/g, '');
const cuts = [
  /(^|\n)\s*On [\s\S]{0,300}?wrote:/i,
  /(^|\n)-{2,}\s*Original Message\s*-{2,}/i,
  /(^|\n)_{5,}/,
  /(^|\n)From:\s[^\n]+\n(Sent|Date):/i,
  /(^|\n)Sent from my /i,
];
for (const re of cuts) {
  const i = clean.search(re);
  if (i > 0) clean = clean.slice(0, i);
}
clean = clean.split('\n').filter((l) => !l.trim().startsWith('>')).join('\n').replace(/\n{3,}/g, '\n\n').trim();
const wordCount = (clean.match(/\S+/g) || []).length;
const opening = clean.slice(0, 300);

const autoSubmitted = header('auto-submitted');
const isBounce = /mailer-daemon|postmaster/i.test(fromEmail) ||
  /delivery status notification|undeliverable|delivery (has )?failed|mail delivery (failed|subsystem)|returned mail|address not found/i.test(subject);
const isAuto = (autoSubmitted && !/^no$/i.test(autoSubmitted)) || !!header('x-autoreply') || !!header('x-autorespond') ||
  /auto_reply/i.test(header('precedence')) ||
  /(out of (the )?office|automatic reply|auto[- ]?reply|autoreply|on leave|away from (the )?office)/i.test(subject);
const isOptOut = /\bunsubscribe\b/i.test(subject) ||
  /\b(unsubscribe|remove me|take me off|opt[ -]?out|do not (contact|email) me|don'?t (contact|email) me|stop (emailing|contacting|sending))\b/i.test(opening) ||
  (wordCount <= 5 && /\bstop\b/i.test(clean));

const kind = isBounce ? 'bounce' : isAuto ? 'auto_reply' : isOptOut ? 'opt_out' : 'reply';

return {
  json: {
    kind,
    gmail_id: m.id,
    thread_id: m.threadId,
    from_email: fromEmail,
    subject,
    body: clean.slice(0, 4000),
    snippet: clean.slice(0, 600),
  },
};

